// The Nexus card archive. The data lives in cards.json (generated by
// scripts/fetch-cards.mjs from Scryfall — authoring-time only) and is read
// here at startup.
//
// It used to be a ~25 MB / 700k-line `export const MOCK_CARDS = [...]`
// literal. tsx re-transformed that whole module on every server boot —
// several seconds of CPU and enough memory to fail Render's free tier, which
// left the live API stuck on an old deploy. `JSON.parse` of the same bytes is
// ~100 ms and costs almost nothing.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import type { Card } from "./types";

const CARDS_JSON = fileURLToPath(new URL("./cards.json", import.meta.url));

export const MOCK_CARDS: Card[] = JSON.parse(readFileSync(CARDS_JSON, "utf8")) as Card[];
